export interface NoteItem {
  id: string;
  title: string;
  content: string;
}

export interface GraphData {
  nodes: { id: string; label: string }[];
  links: { source: string; target: string }[];
  backlinks: Record<string, string[]>;
}

export function buildWikiGraph(notes: NoteItem[]): GraphData {
  const nodes = notes.map(n => ({ id: n.id, label: n.title }));
  const links: { source: string; target: string }[] = [];
  const backlinks: Record<string, string[]> = {};
  const titleToId = new Map(notes.map(n => [n.title.toLowerCase().trim(), n.id]));

  for (const note of notes) {
    const matches = Array.from(note.content.matchAll(/\[\[([^\]\|]+)(?:\|[^\]]+)?\]\]/g));
    for (const match of matches) {
      const targetTitle = match[1].toLowerCase().trim();
      const targetId = titleToId.get(targetTitle);
      if (targetId && targetId !== note.id) {
        links.push({ source: note.id, target: targetId });
        if (!backlinks[targetId]) backlinks[targetId] = [];
        if (!backlinks[targetId].includes(note.id)) backlinks[targetId].push(note.id);
      }
    }
  }
  return { nodes, links, backlinks };
}
